// ── Engine ───────────────────────────────────────────────────────────────────
const KD_TAG = "__kashaKdBg__";

// ── Pattern recolour engine ────────────────────────────────────────────────────
// Mirrors the GT015 recolorImage algorithm from the pasted reference code.
// Channel A replaces dark / near-black pixels (#000000).
// Channel B replaces light / near-pink pixels  (#F0CED2).

export interface RecolorOptions {
  /** Hex colour that replaces Channel A — dark/black pixels (default #000000) */
  colorA: string;
  /** Hex colour that replaces Channel B — light/pink pixels (default #F0CED2) */
  colorB: string;
}

/** Source colours baked into the KA.SHA design PNGs */
const SRC_A = { r: 0,   g: 0,   b: 0   };       // #000000 — black
const SRC_B = { r: 240, g: 206, b: 210 };        // #F0CED2 — pink
const TOLERANCE = 60;

function hexToRgb(hex: string): { r: number; g: number; b: number } {
  return {
    r: parseInt(hex.slice(1, 3), 16),
    g: parseInt(hex.slice(3, 5), 16),
    b: parseInt(hex.slice(5, 7), 16),
  };
}
function colorDist(r1: number, g1: number, b1: number, r2: number, g2: number, b2: number): number {
  return Math.sqrt((r1 - r2) ** 2 + (g1 - g2) ** 2 + (b1 - b2) ** 2);
}

/** Recolor a canvas: near-black → colorA, near-pink → colorB. Returns a new canvas. */
function recolorCanvas(src: HTMLCanvasElement, cA_hex: string, cB_hex: string): HTMLCanvasElement {
  const w = src.width, h = src.height;
  const out = document.createElement("canvas");
  out.width = w; out.height = h;
  const ctx = out.getContext("2d")!;
  ctx.drawImage(src, 0, 0);
  const imgData = ctx.getImageData(0, 0, w, h);
  const pix = imgData.data;
  const nA = hexToRgb(cA_hex);
  const nB = hexToRgb(cB_hex);
  for (let i = 0; i < pix.length; i += 4) {
    const r = pix[i], g = pix[i + 1], b = pix[i + 2];
    const dA = colorDist(r, g, b, SRC_A.r, SRC_A.g, SRC_A.b);
    const dB = colorDist(r, g, b, SRC_B.r, SRC_B.g, SRC_B.b);
    if (dA <= dB && dA < TOLERANCE) {
      const t = Math.max(0, 1 - dA / TOLERANCE);
      pix[i]     = Math.round(r * (1 - t) + nA.r * t);
      pix[i + 1] = Math.round(g * (1 - t) + nA.g * t);
      pix[i + 2] = Math.round(b * (1 - t) + nA.b * t);
    } else if (dB < TOLERANCE) {
      const t = Math.max(0, 1 - dB / TOLERANCE);
      pix[i]     = Math.round(r * (1 - t) + nB.r * t);
      pix[i + 1] = Math.round(g * (1 - t) + nB.g * t);
      pix[i + 2] = Math.round(b * (1 - t) + nB.b * t);
    }
  }
  ctx.putImageData(imgData, 0, 0);
  return out;
}

/** Load a base64/data URL into an offscreen HTMLCanvasElement */
function dataUrlToCanvas(dataUrl: string): Promise<HTMLCanvasElement> {
  return new Promise((res, rej) => {
    const img = new Image();
    img.onload = () => {
      const c = document.createElement("canvas");
      c.width  = img.naturalWidth  || img.width;
      c.height = img.naturalHeight || img.height;
      c.getContext("2d")!.drawImage(img, 0, 0);
      res(c);
    };
    img.onerror = rej;
    img.src = dataUrl;
  });
}

/** Load an image URL into an HTMLImageElement (with CORS) */
function loadImageEl(url: string): Promise<HTMLImageElement> {
  return new Promise((res, rej) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload  = () => res(img);
    img.onerror = rej;
    img.src = url;
  });
}

/** Remove the KA.SHA design layer from the fabric canvas */
export function clearKashaDesign(fc: fabric.Canvas): void {
  fc.getObjects()
    .filter((o) => (o as any).data?.tag === KD_TAG)
    .forEach((o) => fc.remove(o));
}

/** Place zone textures at their UV positions on the fabric canvas.
 *  Pass `recolor` to channel-replace colours in the design PNGs before placing. */
export async function applyKashaDesign(
  fc:      fabric.Canvas,
  design:  KashaDesignDef,
  recolor?: RecolorOptions,
): Promise<void> {
  clearKashaDesign(fc);

  const needsRecolor = recolor && (recolor.colorA !== "#000000" || recolor.colorB !== "#F0CED2");

  const zoneMap: Array<{ key: keyof KashaDesignDef['zones']; zone: keyof typeof ZONE_PRESETS }> = [
    { key: 'front',       zone: 'front'       },
    { key: 'back',        zone: 'back'        },
    { key: 'collar',      zone: 'collar'      },
    { key: 'leftSleeve',  zone: 'leftSleeve'  },
    { key: 'rightSleeve', zone: 'rightSleeve' },
  ];

  const imgs: fabric.FabricImage[] = [];

  for (const { key, zone } of zoneMap) {
    let dataUrl = design.zones[key];
    if (!dataUrl) continue;

    if (needsRecolor) {
      try {
        const srcCanvas  = await dataUrlToCanvas(dataUrl);
        const recolored  = recolorCanvas(srcCanvas, recolor!.colorA, recolor!.colorB);
        dataUrl = recolored.toDataURL("image/png");
      } catch { /* fall through — use original dataUrl */ }
    }

    const preset = { ...ZONE_PRESETS[zone], ...(design.zoneOverrides?.[zone] ?? {}) };
    const img = await fabric.FabricImage.fromURL(dataUrl, { crossOrigin: 'anonymous' });
    img.set({
      left:    preset.left,
      top:     preset.top,
      scaleX:  preset.w / img.width!,
      scaleY:  preset.h / img.height!,
      originX: 'left',
      originY: 'top',
      selectable: true,
      evented:    true,
      data: { tag: KD_TAG, designId: design.id, zone: key },
    } as any);
    imgs.push(img);
  }

  for (const img of imgs) {
    fc.add(img);
    fc.sendObjectToBack(img);
  }
  fc.renderAll();
}

/**
 * Apply a print to the KA.SHA design zones using canvas compositing.
 *
 * Strategy: for each zone PNG (which has the exact pattern shape as opacity),
 * tile the print image across the zone area, then use `destination-in`
 * compositing to clip the print to the opaque pixels of the zone PNG.
 * This puts the print in exactly the same shaped areas that applyKashaDesign
 * colours — with zero pixel-reading (no CORS/getImageData restrictions).
 *
 * The print image is fetched via fetch() → blob URL so it never taints the
 * canvas, ensuring the compositing works in both dev and production.
 */
export async function applyKashaDesignWithPrint(
  fc:            fabric.Canvas,
  design:        KashaDesignDef,
  _patColorA:    string,        // reserved for future channel-A overlay
  printImageUrl: string,
): Promise<void> {
  clearKashaDesign(fc);

  // ── Load print image: fetch → blob URL → img element (no CORS taint) ──────
  const TILE = 192;
  let printEl: HTMLImageElement | null = null;
  let blobUrl: string | null = null;

  try {
    const resp = await fetch(printImageUrl);
    const blob = await resp.blob();
    blobUrl = URL.createObjectURL(blob);
    printEl = await new Promise<HTMLImageElement>((res, rej) => {
      const img = new Image(); // no crossOrigin — blob URLs are same-origin
      img.onload  = () => res(img);
      img.onerror = () => rej(new Error("print load failed"));
      img.src = blobUrl!;
    });
  } catch {
    // Print load failed — fall back to plain coloured zones
    if (blobUrl) URL.revokeObjectURL(blobUrl);
    await applyKashaDesign(fc, design);
    return;
  }

  const zoneMap: Array<{ key: keyof KashaDesignDef["zones"]; zone: keyof typeof ZONE_PRESETS }> = [
    { key: "front",       zone: "front"       },
    { key: "back",        zone: "back"        },
    { key: "collar",      zone: "collar"      },
    { key: "leftSleeve",  zone: "leftSleeve"  },
    { key: "rightSleeve", zone: "rightSleeve" },
  ];

  const imgs: fabric.FabricImage[] = [];

  for (const { key, zone } of zoneMap) {
    const dataUrl = design.zones[key];
    if (!dataUrl) continue;

    const preset = ZONE_PRESETS[zone];
    const W = preset.w, H = preset.h;

    // Create working canvas at the display dimensions of this zone
    const out = document.createElement("canvas");
    out.width  = W;
    out.height = H;
    const ctx = out.getContext("2d")!;

    // Step 1 — tile print across the full zone area
    for (let row = 0; row * TILE < H; row++) {
      for (let col = 0; col * TILE < W; col++) {
        ctx.drawImage(printEl!, col * TILE, row * TILE, TILE, TILE);
      }
    }

    // Step 2 — load zone PNG (data URL, always safe) and use it as a mask.
    // `destination-in` keeps destination (print) pixels only where the source
    // (zone PNG) is non-transparent — i.e. exactly the shaped zone areas.
    const zoneEl = await new Promise<HTMLImageElement>((res, rej) => {
      const img = new Image();
      img.onload  = () => res(img);
      img.onerror = rej;
      img.src = dataUrl;
    });
    ctx.globalCompositeOperation = "destination-in";
    ctx.drawImage(zoneEl, 0, 0, W, H);
    ctx.globalCompositeOperation = "source-over"; // reset

    // Step 3 — add to Fabric canvas at zone position (already at preset size)
    const resultUrl = out.toDataURL("image/png");
    const fImg = await fabric.FabricImage.fromURL(resultUrl, { crossOrigin: "anonymous" });
    fImg.set({
      left:    preset.left,
      top:     preset.top,
      scaleX:  1,
      scaleY:  1,
      originX: "left",
      originY: "top",
      selectable: true,
      evented:    true,
      data: { tag: KD_TAG, designId: design.id, zone: key },
    } as any);
    imgs.push(fImg);
  }

  if (blobUrl) URL.revokeObjectURL(blobUrl);

  for (const img of imgs) {
    fc.add(img);
    fc.sendObjectToBack(img);
  }
  fc.renderAll();
}

